C=/opt/course/s13-comp
yv() { python3 -c "import yaml,sys,json;print(json.dumps(yaml.safe_load(open(sys.argv[1]))))" "$1" 2>/dev/null; }
build() { kubectl kustomize $C/overlays/$1 2>/dev/null | python3 -c "import yaml,sys,json;print(json.dumps([d for d in yaml.safe_load_all(sys.stdin) if d]))"; }
summ() { build $1 | jq -r '(map(select(.kind=="Deployment" or .kind=="Service") | .kind+"/"+.metadata.name) | sort | join(",")) + "|" + ([.[] | select(.kind=="Deployment" and .metadata.name=="shop") | .spec.template.spec.containers[0].env[] | .name+"="+.value] | sort | join(","))'; }
envs() { kubectl -n $1 get deploy shop -o json | jq -r '[.spec.template.spec.containers[0].env[] | .name+"="+.value] | sort | join(",")'; }
guard "base unchanged" 'cd $C/base && sha256sum -c --quiet /root/.s13-comp.sha'
check "external-db is a Component and overlay dev builds" 'yv $C/components/external-db/kustomization.yaml | jq -e ".kind==\"Component\" and (.apiVersion|startswith(\"kustomize.config.k8s.io/v1alpha1\"))" && kubectl kustomize $C/overlays/dev >/dev/null'
check "component caching (kind Component) exists and contains no copy in overlays" 'yv $C/components/caching/kustomization.yaml | jq -e ".kind==\"Component\"" && ! grep -rlq "redis:7-alpine" $C/overlays'
check "dev build: shop only, DB_HOST but no caching" '[ "$(summ dev)" = "Deployment/shop,Service/shop|DB_HOST=postgres.db.example.com,SHOP_MODE=standard" ]'
check "premium build: redis-cache Deployment+Service, DB_HOST and CACHE_HOST" '[ "$(summ premium)" = "Deployment/redis-cache,Deployment/shop,Service/redis-cache,Service/shop|CACHE_HOST=redis-cache,DB_HOST=postgres.db.example.com,SHOP_MODE=standard" ]'
check "selfhosted build: redis-cache and CACHE_HOST, no DB_HOST" '[ "$(summ selfhosted)" = "Deployment/redis-cache,Deployment/shop,Service/redis-cache,Service/shop|CACHE_HOST=redis-cache,SHOP_MODE=standard" ]'
check "redis-cache spec: redis:7-alpine, container redis, Service port 6379 selects it" 'build premium | jq -e "(.[] | select(.kind==\"Deployment\" and .metadata.name==\"redis-cache\") | .spec.template.spec.containers[0] | .name==\"redis\" and .image==\"redis:7-alpine\") and (.[] | select(.kind==\"Service\" and .metadata.name==\"redis-cache\") | .spec.ports[0].port==6379 and .spec.selector.app==\"redis-cache\")"'
check "s13-comp-premium: shop and redis-cache running, shop has CACHE_HOST and DB_HOST" 'for d in shop redis-cache; do kubectl -n s13-comp-premium rollout status deploy/$d --timeout=90s || exit 1; done && [ "$(envs s13-comp-premium)" = "CACHE_HOST=redis-cache,DB_HOST=postgres.db.example.com,SHOP_MODE=standard" ] && [ -n "$(kubectl -n s13-comp-premium get endpointslice -l kubernetes.io/service-name=redis-cache -o jsonpath="{.items[*].endpoints[*].addresses}")" ]'
check "s13-comp-dev: shop running with DB_HOST, no redis-cache" 'kubectl -n s13-comp-dev rollout status deploy/shop --timeout=90s && [ "$(envs s13-comp-dev)" = "DB_HOST=postgres.db.example.com,SHOP_MODE=standard" ] && ! kubectl -n s13-comp-dev get deploy redis-cache'
